content.solution_code:
class MediaContent {
    constructor(title, duration) {
        this.title = title;
        this.duration = duration; // duration in seconds
    }

    _formatDuration() {
        const minutes = Math.floor(this.duration / 60);
        const seconds = this.duration % 60;
        return `${minutes} minutes ${seconds} seconds`;
    }

    play() {
        return `Playing "${this.title}"...`;
    }
}

class PodcastEpisode extends MediaContent {
    constructor(title, duration, host) {
        super(title, duration);
        this.host = host;
    }

    play() {
        return `Playing podcast episode "${this.title}" with host ${this.host}. Duration: ${this._formatDuration()}.`;
    }
}

class MusicTrack extends MediaContent {
    constructor(title, duration, artist) {
        super(title, duration);
        this.artist = artist;
    }

    play() {
        return `Playing music track "${this.title}" by ${this.artist}. Duration: ${this._formatDuration()}.`;
    }
}

